// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { AnimatePresence, motion, useReducedMotion } from "framer-motion";
import { Check, ChevronDown, Loader2, Sparkles } from "lucide-react";
import { cn } from "@/lib/utils";



/* ------------------------------------------------------------------ */
/* Types                                                               */
/* ------------------------------------------------------------------ */

export interface ReasoningAccordionProps {
  /** Reasoning steps. Append to this array while the model is thinking and each new step fades in. */
  steps: string[];
  /** true while the model is reasoning. The panel opens and the timer runs. */
  isThinking: boolean;
  /** Seconds to display. Omit it and the component measures the time itself. */
  duration?: number;
  /** Initial open state. Defaults to open when the component mounts while thinking. */
  defaultOpen?: boolean;
  /** Milliseconds to wait before auto-collapsing after thinking ends. */
  collapseDelay?: number;
  className?: string;
}

const formatDuration = (seconds: number) =>
  seconds < 60 ? `${seconds.toFixed(1)}s` : `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`;



/* ------------------------------------------------------------------ */
/* Component                                                           */
/* ------------------------------------------------------------------ */

export function ReasoningAccordion({
  steps,
  isThinking,
  duration,
  defaultOpen,
  collapseDelay = 1200,
  className,
}: ReasoningAccordionProps) {
  const reduced = !!useReducedMotion();
  const panelId = React.useId();
  const headerId = `${panelId}-header`;

  const [open, setOpen] = React.useState(defaultOpen ?? isThinking);
  const [elapsed, setElapsed] = React.useState(0);
  const collapseTimer = React.useRef<number | undefined>(undefined);
  const wasThinking = React.useRef(isThinking);
  const scrollRef = React.useRef<HTMLDivElement>(null);

  // Live timer: ticks while thinking and keeps the final value afterwards
  React.useEffect(() => {
    if (!isThinking) return;
    const startedAt = performance.now();
    setElapsed(0);
    const id = window.setInterval(() => setElapsed((performance.now() - startedAt) / 1000), 100);
    return () => {
      window.clearInterval(id);
      setElapsed((performance.now() - startedAt) / 1000);
    };
  }, [isThinking]);

  // Open when thinking starts. Collapse a moment after it ends
  React.useEffect(() => {
    if (isThinking) {
      setOpen(true);
    } else if (wasThinking.current) {
      collapseTimer.current = window.setTimeout(() => setOpen(false), collapseDelay);
    }
    wasThinking.current = isThinking;
    return () => window.clearTimeout(collapseTimer.current);
  }, [isThinking, collapseDelay]);

  // Keep the newest step in view while streaming
  React.useEffect(() => {
    const el = scrollRef.current;
    if (el && isThinking) el.scrollTop = el.scrollHeight;
  }, [steps.length, isThinking]);

  // Manual toggle always wins: it also cancels a pending auto-collapse
  const toggle = () => {
    window.clearTimeout(collapseTimer.current);
    setOpen((o) => !o);
  };

  const shown = duration ?? elapsed;
  const pulse = isThinking && !reduced;

  return (
    <div className={cn("w-full overflow-hidden rounded-2xl border border-border bg-muted/30 text-foreground", className)}>
      {/* Screen readers hear state changes, not the ticking timer */}
      <span className="sr-only" role="status">
        {isThinking ? "Thinking" : `Finished thinking after ${formatDuration(shown)}`}
      </span>

      {/* Header */}
      <button
        type="button"
        id={headerId}
        aria-expanded={open}
        aria-controls={panelId}
        onClick={toggle}
        className="flex w-full items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-muted/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
      >
        <span className="relative grid size-8 shrink-0 place-items-center rounded-lg bg-primary/10 text-primary">
          {pulse && (
            <motion.span
              aria-hidden="true"
              className="absolute inset-0 rounded-lg bg-primary/20"
              animate={{ scale: [1, 1.4], opacity: [0.6, 0] }}
              transition={{ duration: 1.4, repeat: Infinity, ease: "easeOut" }}
            />
          )}
          <motion.span
            className="relative"
            animate={pulse ? { scale: [1, 1.15, 1], opacity: [1, 0.7, 1] } : { scale: 1, opacity: 1 }}
            transition={pulse ? { duration: 1.4, repeat: Infinity, ease: "easeInOut" } : { duration: 0.3 }}
          >
            <Sparkles className="size-4" aria-hidden="true" />
          </motion.span>
        </span>

        <span className="flex-1 text-sm font-medium" aria-hidden="true">
          <span className={cn(isThinking && "animate-pulse motion-reduce:animate-none")}>{isThinking ? "Thinking for" : "Thought for"}</span>{" "}
          <span className="tabular-nums text-muted-foreground">{formatDuration(shown)}</span>
        </span>

        {steps.length > 0 && (
          <span className="hidden text-xs text-muted-foreground sm:inline">
            {steps.length} {steps.length === 1 ? "step" : "steps"}
          </span>
        )}

        <motion.span animate={{ rotate: open ? 180 : 0 }} transition={{ duration: reduced ? 0 : 0.25 }} className="text-muted-foreground">
          <ChevronDown className="size-4" aria-hidden="true" />
        </motion.span>
      </button>

      {/* Panel: height animates between 0 and auto */}
      <AnimatePresence initial={false}>
        {open && (
          <motion.div
            key="panel"
            id={panelId}
            role="region"
            aria-labelledby={headerId}
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: reduced ? 0 : 0.3, ease: [0.22, 1, 0.36, 1] }}
            className="overflow-hidden"
          >
            <div ref={scrollRef} className="max-h-72 overflow-y-auto border-t border-border px-4 py-4">
              <ol
                aria-live="polite"
                aria-busy={isThinking}
                className="space-y-3"
              >
                {steps.length === 0 && (
                  <li className="text-sm text-muted-foreground">{isThinking ? "Starting to think…" : "No reasoning steps."}</li>
                )}

                {steps.map((step, i) => {
                  const current = isThinking && i === steps.length - 1;
                  return (
                    <motion.li
                      key={i}
                      initial={reduced ? false : { opacity: 0, y: 8 }}
                      animate={{ opacity: 1, y: 0 }}
                      transition={{ duration: 0.35, ease: "easeOut" }}
                      className="relative flex gap-3 text-sm leading-relaxed after:absolute after:-bottom-3 after:left-2.5 after:top-6 after:w-px after:bg-border last:after:hidden"
                    >
                      <span className="relative z-10 mt-0.5 grid size-5 shrink-0 place-items-center rounded-full border border-border bg-background text-muted-foreground">
                        {current ? <Loader2 className="size-3 animate-spin" aria-hidden="true" /> : <Check className="size-3" aria-hidden="true" />}
                      </span>
                      <span className={current ? "text-foreground" : "text-muted-foreground"}>{step}</span>
                    </motion.li>
                  );
                })}
              </ol>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

